<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {api} from '../api'
import Icon from '../components/Icon.vue'
import PerformanceChart from '../components/PerformanceChart.vue'
import GradeTable from '../components/GradeTable.vue'
import PdfViewer from '../components/PdfViewer.vue'
const month=ref('2026-10'),group=ref(null),evaluation=ref(null),options=ref([]),data=ref(null),error=ref(''),busy=ref(false),exporting=ref(''),pdf=ref(''),showPdf=ref(false),page=ref(1)
function query(){const q=new URLSearchParams();if(month.value)q.set('month',month.value);if(group.value)q.set('group_id',group.value);if(evaluation.value)q.set('evaluation',evaluation.value);return q}
async function load(){busy.value=true;error.value='';try{data.value=await api('/reports?'+query());page.value=1}catch(e){error.value=e.message}finally{busy.value=false}}
async function exportFile(type){exporting.value=type;error.value='';try{let blob;if(type==='excel'){const [data,{createGradeWorkbookBuffer}]=await Promise.all([api('/reports/excel?'+query()),import('../services/gradeWorkbook.js')]);const buffer=await createGradeWorkbookBuffer(data);blob=new Blob([buffer],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})}else blob=await api('/reports/'+type+'?'+query(),{blob:true});const url=URL.createObjectURL(blob);if(type==='pdf'){if(pdf.value)URL.revokeObjectURL(pdf.value);pdf.value=url;showPdf.value=true}else{const a=document.createElement('a');a.href=url;a.download='notas-uls-'+(month.value||'todos')+'.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}catch(e){error.value=e.message}finally{exporting.value=''}}
onMounted(async()=>{try{options.value=(await api('/options')).groups.map(g=>({title:g.code+' · '+g.subject,value:g.id}));await load()}catch(e){error.value=e.message}})
onBeforeUnmount(()=>{if(pdf.value)URL.revokeObjectURL(pdf.value)})
</script>
<template><div class="page-heading"><div><span class="eyebrow">INFORMACIÓN QUE ORIENTA</span><h1>Informes y estadísticas<span class="heading-dot">.</span></h1><p>Una visión clara del rendimiento de tus estudiantes.</p></div><div class="heading-actions"><v-btn variant="outlined" color="primary" @click="exportFile('excel')" :loading="exporting==='excel'"><Icon name="Download" :size="17" class="mr-2"/>Exportar Excel</v-btn><v-btn color="primary" @click="exportFile('pdf')" :loading="exporting==='pdf'"><Icon name="FileText" :size="17" class="mr-2"/>Generar PDF</v-btn></div></div>
<v-alert v-if="error" type="error" variant="tonal" class="mb-5">{{error}}</v-alert>
<section class="panel report-filters"><div><span class="field-label">Período de consulta</span><input v-model="month" type="month" aria-label="Mes del informe" class="month-input"/></div><v-select v-model="group" :items="options" label="Todos los grupos" clearable hide-details/><v-select v-model="evaluation" :items="[{title:'Parcial 1',value:1},{title:'Parcial 2',value:2},{title:'Parcial 3',value:3}]" label="Todas las evaluaciones" clearable hide-details/><v-btn color="primary" variant="tonal" size="large" :loading="busy" @click="load"><Icon name="Search" :size="17" class="mr-2"/>Consultar</v-btn></section>
<div class="report-overview"><article class="panel report-chart"><div class="panel-heading"><div><h2>Resultados del período</h2><p>Estudiantes aprobados y reprobados</p></div><Icon name="ChartNoAxesCombined"/></div><PerformanceChart :passed="data?.passed||0" :failed="data?.failed||0"/></article><div class="report-stat-stack"><article class="panel report-stat"><span class="stat-icon blue"><Icon name="BookOpen"/></span><div><span>Evaluaciones registradas</span><strong>{{data?.grades.length||0}}</strong></div></article><article class="panel report-stat"><span class="stat-icon green"><Icon name="ChartNoAxesCombined"/></span><div><span>Promedio de las evaluaciones</span><strong>{{(data?.average||0).toFixed(2)}} <small>/ 10</small></strong></div></article><div class="report-explainer"><Icon name="CircleHelp" :size="21"/><p>El gráfico cuenta una vez a cada estudiante y usa el promedio de sus notas filtradas. Se aprueba con una nota de <strong>6.00 o más</strong>.</p></div></div></div>
<section class="panel"><div class="panel-heading"><div><h2>Cuadro de notas</h2><p>Los archivos PDF y Excel incluyen todos los resultados de la consulta.</p></div><span class="count-badge">{{data?.grades.length||0}} registros</span></div><GradeTable :rows="data?.grades.slice((page-1)*5,page*5)||[]"/><div class="pagination-bar"><p>5 registros por página</p><v-pagination v-model="page" :length="Math.max(1,Math.ceil((data?.grades.length||0)/5))" :total-visible="5" size="small" active-color="primary"/></div></section>
<v-dialog v-model="showPdf" max-width="1100"><v-card><div class="modal-heading"><div><span class="eyebrow">DOCUMENTO ACADÉMICO</span><h2>Vista previa del informe</h2></div><div class="heading-actions"><v-btn :href="pdf" download="notas-uls.pdf" variant="tonal" color="primary"><Icon name="Download" :size="17" class="mr-2"/>Descargar</v-btn><button @click="showPdf=false" aria-label="Cerrar PDF"><Icon name="X"/></button></div></div><PdfViewer v-if="showPdf" :url="pdf"/></v-card></v-dialog>
</template>
7